#!/usr/bin/env python3
"""Tiny HTTP server for the HLS folder: correct MIME types, no caching."""
# Part of VRChat Stream. Created by Lokinya (lokinyauv-create). Generated by AI (Claude, Anthropic). Apache-2.0.
import http.server
import sys

TYPES = {
    ".m3u8": "application/vnd.apple.mpegurl",
    ".ts": "video/mp2t",
}


class Handler(http.server.SimpleHTTPRequestHandler):
    def guess_type(self, path):
        for ext, mime in TYPES.items():
            if path.endswith(ext):
                return mime
        return super().guess_type(path)

    def end_headers(self):
        self.send_header("Cache-Control", "no-cache")
        self.send_header("Access-Control-Allow-Origin", "*")
        super().end_headers()

    def log_message(self, *args):
        pass


if __name__ == "__main__":
    directory, port = sys.argv[1], int(sys.argv[2])
    handler = lambda *a, **kw: Handler(*a, directory=directory, **kw)
    http.server.ThreadingHTTPServer(("127.0.0.1", port), handler).serve_forever()
